from queue import Queue

from queue import Full

import pytest


def accepted(cap: int, xs: list[int]) -> int:
    """Return how many items of xs were accepted by a bounded int queue.

    A queue with capacity ``cap`` is created, and each element of ``xs``
    is put into it without blocking, in order. Once a put fails because
    the queue is full, stop and return the number of puts that succeeded.

    ``cap == 0`` means the queue can hold nothing, so the result is 0.
    (``queue.Queue(maxsize=0)`` would mean unbounded, so this case must
    be handled explicitly.)

    Raises ValueError if ``cap`` is negative.
    """
    if cap < 0:
        raise ValueError("capacity must be non-negative")
    if cap == 0:
        return 0
    q: Queue[int] = Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except Full:
            break
        count += 1
    return count


def test_accepted_stops_when_full() -> None:
    assert accepted(2, [1, 2, 3]) == 2


def test_accepted_all_fit() -> None:
    assert accepted(3, [1, 2]) == 2
    assert accepted(5, [10, 20, 30]) == 3


def test_accepted_empty_input() -> None:
    assert accepted(5, []) == 0


def test_accepted_capacity_one() -> None:
    assert accepted(1, [7, 8, 9]) == 1


def test_accepted_zero_capacity() -> None:
    assert accepted(0, [1, 2]) == 0


def test_accepted_negative_capacity_raises() -> None:
    with pytest.raises(ValueError):
        accepted(-1, [1])
